tool_and_message_events.command:
/bin/bash -lc "cat > dist/presentation.css <<'EOF'
.sheet {
  width: min(640px, calc(100% - 2 * var(--gap)));
  margin: clamp(16px, 4vw, 36px) auto;
  padding: clamp(16px, 4vw, 24px);
  border-radius: var(--radius);
  background: var(--paper);
  line-height: 1.5;
}

.sheet h1 {
  margin: 0 0 8px;
  font-size: clamp(24px, 4vw, 28px);
  line-height: 1.2;
}

.sheet > p {
  color: var(--subtle);
}

.sheet > h1 + p {
  margin: 0 0 24px;
}

.sheet label {
  display: block;
  margin: var(--gap) 0 6px;
  font-weight: 600;
}

.sheet input,
.sheet select,
.sheet button {
  min-height: 44px;
  border: 1px solid var(--subtle);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

.sheet input,
.sheet select {
  display: block;
  width: 100%;
  padding: 8px 12px;
}

.sheet button {
  padding: 10px 14px;
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.actions {
  display: grid;
  gap: 12px;
  margin-top: 20px;
}

@media (min-width: 576px) {
  .actions {
    grid-template-columns: 1fr auto;
  }
}

.sheet [data-primary] {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--paper);
}

.sheet :is(input, select, button):focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 2px;
}

.sheet input[aria-invalid=\"true\"] {
  border-color: var(--danger);
}

.sheet [role=\"alert\"] {
  margin: 12px 0 0;
  padding-inline-start: 10px;
  border-inline-start: 3px solid var(--danger);
  color: var(--danger);
  font-weight: 600;
}

#saved {
  margin: 20px 0 0;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  overflow-wrap: anywhere;
}

dialog {
  max-width: calc(100vw - 2 * var(--gap));
  padding: var(--gap);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
}

dialog h2 {
  margin-top: 0;
  line-height: 1.25;
}
EOF
if test -f baseline.log; then tail -n 1 baseline.log; fi"

/bin/bash -lc "python - <<'PY'
from pathlib import Path
keep = {Path(Path(f'{name}.log').read_text().splitlines()[-1]).stem for name in ('mobile', 'desktop')}
for path in Path('visits').iterdir():
    if path.stem not in keep and path.suffix in {'.json', '.png'}:
        path.unlink()
for name in ('baseline', 'mobile', 'desktop'):
    Path(f'{name}.log').unlink()
PY
rg --files dist visits"

